ry" href="{{ route('expenses.index') }}">Cancel</a></div></div></div></form>@push('scripts')<script>const budget=document.getElementById('budget_id'),amount=document.getElementById('amount'),remaining=document.getElementById('remaining'),warning=document.getElementById('budget-warning');function updateBudget(){const selected=budget.options[budget.selectedIndex],value=Number(selected.dataset.remaining||0),spent=Number(amount.value||0);remaining.textContent='Remaining: '+value.toFixed(2);warning.classList.toggle('d-none',spent<=value)}budget.addEventListener('change',updateBudget);amount.addEventListener('input',updateBudget);updateBudget();</script>
